def transform(grid):
    g = np.array(grid).copy()
    h, w = g.shape
    mid = h // 2
    bg = 4
    for x in range(0, w, 3):
        g[mid, x] = 6
        for y in range(h):
            if y != mid and grid[y][x] == bg:
                g[y, x] = 6
        emit(g, f"Column {x} (every third from the left): middle cell and the outer cell that was 4 become 6, forming a 2-cell bar.")
    emit(g, "All every-third columns marked; final output.")
    return g
